         {
            i = 0;
            while(true)
            {
               if(i < this.keyNum)
               {
                  if(Main.player1._keyArr[i] == -1)
                  {
                     break;
                  }
                  if(Main.player2._keyArr[i] == -1)
                  {
                     return false;
                  }
                  continue;
               }
               i++;
            }
            return false;
         }
         for(i = 0; i < this.keyNum; i++)
         {
            if(Main.player1._keyArr[i] == -1)
            {
               return false;
            }
         }
         return true;
      }

