private function getIddo(duNum:Number, type:Number = 1) : Boolean
      {
         var i:uint = 0;
         var nmapId:Array = this.getGoodsId() as Array;
         var nstr:Number = this.getTs();
         if(nmapId.length != 1)
         {
            trace("有多个指定地图");
            i = 0;
            while(true)
            {
               if(i < nmapId.length)
               {
                  if(nmapId[i].getValue() == this._map.getValue())
                  {
                     if(nstr == this._star.getValue())
                     {
                        if(this.isRy())
                        {
                           break;
                        }
                        if(this._tg)
                        {
                           return this.dbNum(type,duNum);
                        }
                     }
                  }
                  continue;
               }
               i++;
            }
            return this.dbNum(type,duNum);
         }
         if(nmapId[0].getValue() == -1)
         {
            trace("没有地图要求");
            if(nstr == -1)
            {
               if(this.isRy())
               {
                  trace("无通关要求");
                  return this.dbNum(type,duNum);
               }
               trace("通关要求YES",this._tg);
               if(this._tg)
               {
                  return this.dbNum(type,duNum);
               }
            }
            else if(nstr == this._star.getValue())
            {
               if(this.isRy())
               {
                  trace("无通关要求");
                  return this.dbNum(type,duNum);
               }
               trace("通关要求YES",this._tg);
               if(this._tg)
               {
                  return this.dbNum(type,duNum);
               }
            }
         }
         else
         {
            trace("有指定地图1个");
            trace("地图要求:" + nmapId[0].getValue(),"现在的地图:" + this._map.getValue(),"星级要求:" + nstr,"现在的星级:" + this._star.getValue());
            if(nmapId[0].getValue() == this._map.getValue() && nstr == this._star.getValue())
            {
               if(this.isRy())
               {
                  trace("无通关要求");
                  return this.dbNum(type,duNum);
               }
               trace("通关要求YES",this._tg);
               if(this._tg)
               {
                  return this.dbNum(type,duNum);
               }
            }
         }
         return false;
      }

